<?php
namespace Tests\Feature;
use App\Models\{User,TimetablePlan as Plan,TimetablePlanEntry as Entry,TimetableOptimisationRun as Run,TimetableRoom as Room,TutorGroup,TrainingSession};
use App\Support\{AnnualTimetable as A,CentrePlanning as P,TimetableOptimiser as O,ReviewedImports as H,TimetableGovernance as G};
use Illuminate\Foundation\Testing\LazilyRefreshDatabase;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Str;
use Illuminate\Validation\ValidationException;
use PHPUnit\Framework\Attributes\TestWith;
use Tests\Support\AuditFault;
use Tests\TestCase;
class AnnualTimetableTest extends TestCase {
 use LazilyRefreshDatabase;
 private function publish(User$u,array$args):Plan{$p=P::save($u,1,null,0,(string)Str::uuid(),$args);P::check($u,1,$p,1,true);P::publish($u,1,$p->refresh(),2);return$p->refresh();}
 private function f():array{
  $this->travelTo(now()->setDate(2026,11,15)->setTime(10,0));$admin=User::factory()->create(['role'=>'admin']);$one=User::factory()->create(['role'=>'staff']);$two=User::factory()->create(['role'=>'staff']);$dates=['2026-11-16','2027-10-11'];foreach([$one,$two]as$person)P::windows($admin,1,$person,$dates,H::hash(P::windowSource($person,$dates)),true,'09:00','17:00');
  $base=['staff_id'=>$two->id,'date'=>$dates[0],'weeks'=>1,'start'=>'09:00','end'=>'10:00','kind'=>'Admin','site'=>'Remote','room_id'=>null,'group_id'=>null,'headcount'=>null,'title'=>'Fictional fixed diary'];$fixed=$this->publish($admin,$base);$p=$this->publish($admin,[...$base,'staff_id'=>$one->id,'date'=>$dates[1],'start'=>'15:00','end'=>'16:00','title'=>'Fictional annual activity']);$d=['from'=>'2026-11-16','to'=>'2027-11-15','plans'=>[$p->id],'date_mode'=>'year','staff_options'=>[$p->id=>[$two->id]]];return compact('admin','one','two','dates','base','fixed','p','d');
 }
 private function reject(callable$fn):void{try{$fn();$this->fail('Expected refusal');}catch(ValidationException$e){$this->assertNotEmpty($e->errors());}}
 private function saved(array$f):Run{$v=A::preview($f['admin'],$f['d']);$this->assertTrue($v['can_apply']);return A::prepare($f['admin'],1,$f['d'],$v['source_hash'],(string)Str::uuid(),'Fictional agreed annual arrangements',true);}
 private function apply(array$f,Run$r):Run{return O::apply($f['admin'],1,$r,1,$r->details_hash,true);}
 public function test_whole_year_preview_moves_to_a_nominated_staff_member_and_checked_date_without_writes():void{$f=$this->f();$before=[Plan::count(),Run::count(),DB::table('timetable_planning_events')->count()];$v=A::preview($f['admin'],$f['d']);$s=$v['suggestion'][$f['p']->id];$this->assertTrue($v['can_apply']);$this->assertSame($f['two']->id,$s['after']['staff_id']);$this->assertSame('2026-11-16',$s['after']['date']);$this->assertSame(1,$v['after'][0]);$this->assertSame(2,$v['before'][0]);$this->assertSame(0,$v['after'][1]);$this->assertSame($before,[Plan::count(),Run::count(),DB::table('timetable_planning_events')->count()]);$this->assertFalse($v['search']['global_optimum_proved']);}
 public function test_apply_rechecks_and_replaces_atomically_without_attendance_or_assignment_changes():void{$f=$this->f();$r=$this->apply($f,$this->saved($f));$p=Plan::findOrFail($r->receipt['replacements'][$f['p']->id]);$this->assertSame('Applied',$r->state);$this->assertSame('Withdrawn',$f['p']->fresh()->state);$this->assertTrue(P::published($p));$this->assertSame([],P::inspect($p)['errors']);$this->assertSame($f['two']->id,$p->source['data']['args']['staff_id']);$this->assertSame(60,P::minutes($p->source['data']['args']['end'])-P::minutes($p->source['data']['args']['start']));$this->assertDatabaseCount('training_sessions',0);$this->assertDatabaseCount('attendance_marks',0);$this->assertDatabaseCount('learning_tasks',0);}
 public function test_exact_replays_create_no_duplicate_plans_or_history():void{$f=$this->f();$r=$this->saved($f);$out=$this->apply($f,$r);$before=[Plan::count(),DB::table('timetable_planning_events')->count()];$again=$this->apply($f,$r);$this->assertSame($out->receipt,$again->receipt);$this->assertSame($before,[Plan::count(),DB::table('timetable_planning_events')->count()]);}
 public function test_staff_suitability_must_be_confirmed_before_prepare():void{$f=$this->f();$v=A::preview($f['admin'],$f['d']);$this->reject(fn()=>A::prepare($f['admin'],1,$f['d'],$v['source_hash'],(string)Str::uuid(),'Fictional missing staff confirmation'));$this->assertDatabaseCount('timetable_optimisation_runs',0);}
 public function test_changed_alternative_window_invalidates_prepared_source():void{$f=$this->f();$r=$this->saved($f);P::windows($f['admin'],1,$f['two'],[$f['dates'][0]],H::hash(P::windowSource($f['two'],[$f['dates'][0]])),true,'08:00','17:00');$this->reject(fn()=>$this->apply($f,$r));$this->assertSame('Published',$f['p']->fresh()->state);}
 public function test_new_busy_activity_after_prepare_invalidates_proposal():void{$f=$this->f();$r=$this->saved($f);$this->publish($f['admin'],[...$f['base'],'start'=>'10:00','end'=>'11:00','title'=>'Fictional new reservation']);$this->reject(fn()=>$this->apply($f,$r));}
 public function test_changed_alternative_account_or_governance_blocks_apply():void{$f=$this->f();$r=$this->saved($f);$f['two']->forceFill(['active'=>false])->save();$this->reject(fn()=>$this->apply($f,$r));$this->assertSame('Prepared',$r->fresh()->state);}
 public function test_final_audit_failure_rolls_back_every_reservation():void{$f=$this->f();$r=$this->saved($f);$before=DB::table('timetable_planning_events')->count();AuditFault::install('annual54_fault','timetable_planning_events','Fictional annual fault','annual_applied');try{$this->apply($f,$r);$this->fail('Expected database rollback');}catch(\Illuminate\Database\QueryException){}$this->assertSame('Published',$f['p']->fresh()->state);$this->assertSame('Prepared',$r->fresh()->state);$this->assertDatabaseCount('timetable_plans',2);$this->assertSame($before,DB::table('timetable_planning_events')->count());}
 public function test_cancellation_leaves_original_reservations_intact():void{$f=$this->f();$r=$this->saved($f);O::cancel($f['admin'],1,$r,1,$r->details_hash);$this->assertSame('Cancelled',$r->fresh()->state);$this->assertSame('Published',$f['p']->fresh()->state);$this->reject(fn()=>$this->apply($f,$r));}
 public function test_expiry_and_damaged_details_cannot_apply():void{$f=$this->f();$r=$this->saved($f);$this->travel(31)->minutes();$this->reject(fn()=>$this->apply($f,$r));$r->details_hash=str_repeat('0',64);$r->save();$this->reject(fn()=>$this->apply($f,$r));}
 public function test_53_weekly_dates_and_explicit_holidays_create_exact_published_occurrences():void{$f=$this->f();$dates=P::dates('2026-11-16',53);$this->assertCount(53,$dates);$excluded=[$dates[5],$dates[6]];$kept=P::dates('2026-11-16',53,true,$excluded);P::windows($f['admin'],1,$f['one'],$kept,H::hash(P::windowSource($f['one'],$kept)),true,'09:00','17:00');$p=$this->publish($f['admin'],[...$f['base'],'staff_id'=>$f['one']->id,'weeks'=>53,'excluded_dates'=>$excluded,'start'=>'11:00','end'=>'12:00']);$this->assertCount(51,$p->source['data']['rows']);$this->assertSame($kept,Entry::where('plan_id',$p->id)->orderBy('work_date')->get()->map(fn($e)=>$e->work_date->toDateString())->all());$this->assertTrue(P::fresh($p));$this->assertNotContains($excluded[0],array_column(P::liveRows($p),'work_date'));}
 public function test_invalid_holidays_duplicates_empty_series_and_outside_year_refused():void{$this->f();foreach([['2027-02-30'],['2026-11-16','2026-11-16'],['2026-11-16']]as$excluded)$this->reject(fn()=>P::dates('2026-11-16',1,true,$excluded));$this->reject(fn()=>P::dates('2026-11-16',54));$this->reject(fn()=>A::range('2026-11-16','2027-11-16'));}
 public function test_full_year_http_page_preview_and_existing_saved_decision_routes_work():void{$f=$this->f();$this->actingAs($f['admin'])->get('/centre-planning/year')->assertOk()->assertSee('Plan the full year')->assertSee('Fictional annual activity')->assertHeader('Cache-Control','no-store, private')->assertHeader('Referrer-Policy','no-referrer');$this->post('/centre-planning/year/preview',$f['d'])->assertOk()->assertSee('Save full-year proposal for final check');$r=$this->saved($f);$this->get('/centre-planning/optimiser/'.$r->id)->assertOk()->assertSee('Every original and proposed activity')->assertSee('Apply reviewed timetable changes');}
 public function test_http_prepare_requires_staff_attestation_and_final_apply_arrangements():void{$f=$this->f();$v=A::preview($f['admin'],$f['d']);$post=[...$f['d'],'source_hash'=>$v['source_hash'],'request_token'=>(string)Str::uuid(),'reason'=>'Fictional agreed arrangements','confirmed'=>1];$this->actingAs($f['admin'])->withSession(['auth_version'=>1])->postJson('/centre-planning/year/prepare',$post)->assertUnprocessable();$this->post('/centre-planning/year/prepare',[...$post,'staff_suitability'=>1])->assertRedirect();$r=Run::firstOrFail();$this->postJson('/centre-planning/optimiser/'.$r->id.'/apply',['version'=>1,'details_hash'=>$r->details_hash,'confirmed'=>1])->assertUnprocessable();$this->assertSame('Published',$f['p']->fresh()->state);}
 #[TestWith(['tutor'])] #[TestWith(['apprentice'])] #[TestWith(['employer'])] #[TestWith(['staff'])]
 public function test_ungranted_roles_cannot_read_or_post_year_plans(string$role):void{$u=User::factory()->create(['role'=>$role]);$this->actingAs($u)->get('/centre-planning/year')->assertForbidden();$this->postJson('/centre-planning/year/preview',[])->assertForbidden();$this->postJson('/centre-planning/year/prepare',[])->assertForbidden();}
 public function test_another_manager_cannot_view_or_apply_creators_proposal():void{$f=$this->f();$r=$this->saved($f);$other=User::factory()->create(['role'=>'admin']);$this->actingAs($other)->get('/centre-planning/optimiser/'.$r->id)->assertNotFound();$this->postJson('/centre-planning/optimiser/'.$r->id.'/apply',['version'=>1,'details_hash'=>$r->details_hash,'confirmed'=>1,'arrangements_checked'=>1])->assertForbidden();}
 public function test_teaching_and_private_responsibilities_cannot_transfer_to_a_nominated_staff_pool():void{$f=$this->f();$p=$this->publish($f['admin'],[...$f['base'],'staff_id'=>$f['one']->id,'date'=>$f['dates'][1],'kind'=>'Learner support','title'=>'Fictional support slot']);$d=[...$f['d'],'plans'=>[$p->id],'staff_options'=>[$p->id=>[$f['two']->id]]];$this->reject(fn()=>A::preview($f['admin'],$d));}
 public function test_linked_occurrences_and_partly_delivered_series_are_protected():void{$f=$this->f();$e=Entry::where('plan_id',$f['p']->id)->first();$e->link_proof=['held'=>'fixture'];$e->save();$this->reject(fn()=>A::preview($f['admin'],$f['d']));$e->link_proof=null;$e->save();$this->travelTo(now()->setDate(2027,10,12));$this->reject(fn()=>A::preview($f['admin'],[...$f['d'],'from'=>'2027-10-12','to'=>'2027-11-15']));}
 public function test_unknown_working_dates_never_become_free_candidates():void{$f=$this->f();$v=A::preview($f['admin'],[...$f['d'],'staff_options'=>[]]);$this->assertSame('2026-11-16',$v['from']);foreach($v['suggestion']as$s)$this->assertContains($s['after']['date'],$f['dates']);}
 public function test_stale_or_duplicate_request_cannot_rebind_a_proposal():void{$f=$this->f();$v=A::preview($f['admin'],$f['d']);$token=(string)Str::uuid();$r=A::prepare($f['admin'],1,$f['d'],$v['source_hash'],$token,'Fictional exact arrangements',true);$again=A::prepare($f['admin'],1,$f['d'],$v['source_hash'],$token,'Fictional exact arrangements',true);$this->assertSame($r->id,$again->id);$this->reject(fn()=>A::prepare($f['admin'],1,$f['d'],$v['source_hash'],$token,'Different arrangements',true));}
 public function test_protected_allocation_is_not_ignored_by_full_year_mode():void{$f=$this->f();$ceo=User::factory()->create(['role'=>'ceo']);G::allocation($ceo,1,$f['p'],0,1,true,true,'Fictional protected annual activity');$this->reject(fn()=>A::preview($f['admin'],$f['d']));}
 public function test_invalid_choice_maps_or_duplicate_plan_ids_are_rejected():void{$f=$this->f();$this->reject(fn()=>A::preview($f['admin'],[...$f['d'],'plans'=>[$f['p']->id,$f['p']->id]]));$this->reject(fn()=>A::preview($f['admin'],[...$f['d'],'staff_options'=>['unselected'=>[$f['two']->id]]]));}
 public function test_alternative_room_and_explicit_teaching_dates_keep_primary_tutor_group_and_duration():void{
  $f=$this->f();$tutor=User::factory()->create(['role'=>'tutor']);P::windows($f['admin'],1,$tutor,$f['dates'],H::hash(P::windowSource($tutor,$f['dates'])),true,'09:00','17:00');$g=TutorGroup::factory()->create(['tutor_id'=>$tutor->id,'active'=>true]);$rooms=Room::where('site','Doncaster')->take(2)->get();foreach($rooms as$r)P::room($f['admin'],1,$r,$r->version,['capacity'=>20,'uses'=>['Teaching','Admin'],'active'=>true]);$first=$rooms[0];$second=$rooms[1];
  $this->publish($f['admin'],[...$f['base'],'staff_id'=>$tutor->id,'title'=>'Fictional Tutor fixed work']);$this->publish($f['admin'],[...$f['base'],'start'=>'10:00','end'=>'17:00','site'=>'Doncaster','room_id'=>$first->id,'title'=>'Fictional occupied room']);$p=$this->publish($f['admin'],[...$f['base'],'staff_id'=>$tutor->id,'date'=>$f['dates'][1],'start'=>'15:00','end'=>'16:00','kind'=>'Teaching','group_id'=>$g->id,'headcount'=>20,'site'=>'Doncaster','room_id'=>$first->id,'title'=>'Fictional teaching year plan']);$d=[...$f['d'],'plans'=>[$p->id],'staff_options'=>[],'room_options'=>[$p->id=>[$second->id]],'teaching_dates'=>true];$v=A::preview($f['admin'],$d);$this->assertTrue($v['can_apply']);$after=$v['suggestion'][$p->id]['after'];$this->assertSame($f['dates'][0],$after['date']);$this->assertSame($second->id,$after['room_id']);$this->assertSame($tutor->id,$after['staff_id']);$this->assertSame($g->id,$after['group_id']);$this->assertSame(60,P::minutes($after['end'])-P::minutes($after['start']));$this->assertDatabaseCount('training_sessions',0);
 }
 public function test_whole_year_recurring_preview_retains_every_exclusion_without_inventing_free_days():void{$f=$this->f();P::withdraw($f['admin'],1,$f['p'],$f['p']->version,'Fictional superseded fixture');$all=P::dates('2026-11-16',53);$excluded=[$all[5],$all[6]];$dates=P::dates('2026-11-16',53,true,$excluded);P::windows($f['admin'],1,$f['one'],$dates,H::hash(P::windowSource($f['one'],$dates)),true,'09:00','17:00');$p=$this->publish($f['admin'],[...$f['base'],'staff_id'=>$f['one']->id,'weeks'=>53,'excluded_dates'=>$excluded,'start'=>'11:00','end'=>'12:00','title'=>'Fictional annual recurring work']);$v=A::preview($f['admin'],[...$f['d'],'plans'=>[$p->id],'staff_options'=>[],'date_mode'=>'fixed']);$this->assertSame($dates,$v['suggestion'][$p->id]['proposed_dates']);$this->assertSame($excluded,$v['suggestion'][$p->id]['after']['excluded_dates']);$this->assertSame(51,$v['suggestion'][$p->id]['occurrences']);$this->assertFalse($v['can_apply']);}

 public function test_ceo_review_preserves_protection_on_the_replacement_instead_of_dropping_it():void{$f=$this->f();$originalAdmin=$f['admin'];$ceo=User::factory()->create(['role'=>'ceo']);G::allocation($ceo,1,$f['p'],0,1,true,true,'Fictional protected source');$f['admin']=$ceo;$r=$this->apply($f,$this->saved($f));$new=Plan::findOrFail($r->receipt['replacements'][$f['p']->id]);$c=\App\Models\TimetableAllocationControl::findOrFail($new->id);$this->assertTrue($c->restricted);$this->assertTrue($c->ceo_locked);$this->assertTrue(G::allocationIntact($c));$this->reject(fn()=>G::guardPlan($originalAdmin,$new));$this->assertSame('Published',$new->state);}

 public function test_year_of_alternative_dates_keeps_the_best_checked_choice_with_a_bounded_candidate_pool():void{$f=$this->f();$third=User::factory()->create(['role'=>'staff']);$dates=P::dates('2026-11-16',53);P::windows($f['admin'],1,$third,$dates,H::hash(P::windowSource($third,$dates)),true,'09:00','17:00');$this->publish($f['admin'],[...$f['base'],'staff_id'=>$third->id,'title'=>'Fictional yearly candidate anchor']);$v=A::preview($f['admin'],[...$f['d'],'staff_options'=>[$f['p']->id=>[$third->id]]]);$this->assertGreaterThan(100,$v['search']['examined']);$this->assertSame($third->id,$v['suggestion'][$f['p']->id]['after']['staff_id']);$this->assertSame($dates[0],$v['suggestion'][$f['p']->id]['after']['date']);$this->assertTrue($v['can_apply']);}

}
